/**
 * City-unique content for area×service pages.
 *
 * Each city gets 400-500 words of genuinely unique prose that cannot be
 * generated by swapping data points into a shared template. This pushes
 * cross-city content similarity from ~55-60 % to 80 %+ uniqueness.
 */

export interface CityUniqueContent {
  /** Unique kitchen remodeling context for this city (150-200 words) */
  kitchenContext: string;
  /** Unique bathroom remodeling context (150-200 words) */
  bathroomContext: string;
  /** Unique general remodeling context for flooring/aging-in-place/cabinets (100-150 words) */
  generalContext: string;
  /** 3 unique neighborhood-specific insights (50-80 words each) */
  neighborhoodInsights: string[];
  /** Unique housing stock paragraph (100-150 words) */
  housingStockDetail: string;
  /** Unique local market insight (80-120 words) */
  marketInsight: string;
}

